() => { 
  const h2s = document.querySelectorAll('h2, h3');
  const arr = [];
  h2s.forEach(h => arr.push(h.textContent.trim()));
  return arr;
}

() => { 
  const all = document.body.innerText;
  const match = all.match(/([\d,]+)\s*个结果/);
  if (match) {
    return match[1];
  }
  return 'Not found';
}

() => {
  // Find and click the close button on popup if exists
  const closeButtons = document.querySelectorAll('button[aria-label="close"], button[aria-label="Close"], [aria-label="close"], [aria-label="Close"]');
  if (closeButtons.length > 0) {
    closeButtons[0].click();
    return 'closed via aria-label';
  }
  // Try Escape
  document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true}));
  return 'tried escape, found: ' + closeButtons.length;
}

() => {
  // Look for the count text
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.children.length === 0) {
      const text = el.textContent.trim();
      if (text.includes('个结果')) {
        return text;
      }
    }
  }
  return 'not found';
}

() => {
  // Look for the count of results in the DOM
  const xpath = "//*[contains(text(), '个结果')]";
  const result = document.evaluate(xpath, document, null, XPathResult.ANY_TYPE, null);
  const node = result.iterateNext();
  if (node) {
    return node.textContent;
  }
  return 'Not found';
}

() => {
  // Try to get all text nodes  
  const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );
  let node;
  while (node = walker.nextNode()) {
    const text = node.textContent.trim();
    if (text.match(/^[\d,]+\s*(个结果|results)/)) {
      return text;
    }
  }
  return 'no match';
}

() => {
  const headers = document.querySelectorAll('h2');
  for (const h of headers) {
    const text = h.textContent.trim();
    if (text.includes('结果') || text.includes('result')) {
      return text;
    }
  }
  return 'no h2 with count found';
}

() => {
  const headers = document.querySelectorAll('h2');
  let result = 'no h2';
  for (const h of headers) {
    const text = h.textContent.trim();
    if (text.includes('结果')) {
      result = text;
      break;
    }
  }
  const output = document.createElement('div');
  output.id = 'my-count-output';
  output.textContent = 'RESULT: ' + result;
  output.style.cssText = 'position:fixed;top:0;left:0;background:yellow;color:black;font-size:24px;font-weight:bold;padding:20px;z-index:99999;';
  document.body.appendChild(output);
  return result;
}

() => {
  const allText = document.body.innerText;
  // Find the count by looking for number followed by 个结果 pattern
  const matches = allText.match(/[\d,]+\s*个结果/g);
  return matches ? matches.join(', ') : 'no match found';
}

() => {
  // Find the count by looking for the entire element with 个结果
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    const ownText = el.textContent;
    if (ownText && ownText.includes('个结果') && el.children.length === 0) {
      return 'TEXT: ' + ownText;
    }
  }
  // Look for any element with HTML containing 个结果
  const allWithText = document.querySelectorAll('div, h2, h3, span, p');
  for (const el of allWithText) {
    const html = el.innerHTML;
    if (html && html.includes('个结果') && el.children.length < 5) {
      return 'HTML: ' + html.substring(0, 200);
    }
  }
  return 'no match found';
}

() => {
  // Get the parent that contains "个结果" 
  const allElements = document.querySelectorAll('div, span, h2, p, h1');
  const results = [];
  for (const el of allElements) {
    const directText = Array.from(el.childNodes)
      .filter(n => n.nodeType === Node.TEXT_NODE)
      .map(n => n.textContent.trim())
      .join('');
    if (directText.includes('个结果') || directText.match(/^[\d,]+$/)) {
      results.push({
        tag: el.tagName,
        directText: directText,
        fullText: el.textContent.substring(0, 100)
      });
    }
  }
  return JSON.stringify(results.slice(0, 20));
}

async () => {
  try {
    const response = await fetch('https://www.coursera.org/api/search/v2?query=data%20analysis&productDifficultyLevel=Beginner&productDuration=1-3%20Months&limit=1');
    const data = await response.json();
    return JSON.stringify({paging: data.paging, total: data.paging?.total, or_elements: data.elements?.length});
  } catch (e) {
    return 'Error: ' + e.message;
  }
}

() => {
  // Find the DOM element containing the count by traversing
  const h2 = document.querySelector('h2, [role="heading"]');
  let parent = document.body;
  while (parent) {
    const text = parent.textContent || '';
    if (text.indexOf('个结果') !== -1) {
      // Found parent with the text
      const fullText = parent.textContent.substring(0, 500);
      const html = parent.outerHTML.substring(0, 1000);
      return JSON.stringify({text: fullText, html: html});
    }
    parent = parent.firstElementChild;
  }
  return 'not found';
}

() => {
  // Find the result count element more precisely
  // Look for an element that has only "个结果" or "results" related text
  const resultDivs = [];
  const allElements = document.querySelectorAll('h2, h3, div, span, p');
  for (const el of allElements) {
    const text = el.textContent.trim();
    if (text.includes('个结果') || text.includes('Result')) {
      // Only collect direct text-containing elements
      if (el.children.length < 10 && text.length < 200) {
        resultDivs.push({
          tag: el.tagName,
          text: text.substring(0, 150),
          innerHTML: el.innerHTML.substring(0, 400)
        });
      }
    }
  }
  return JSON.stringify(resultDivs.slice(0, 5));
}
